from pathlib import Path
import re
p=Path("index.html")
s=p.read_text(encoding="utf-8")

def req(old,new,count=1):
    global s
    if old not in s:
        raise SystemExit("missing marker: "+old[:200])
    s=s.replace(old,new,count)

