share_css='/* ===== v1.18.5 每篇分享圖文字樣式 ===== */\n.share-text-style{\n  margin:14px 0 12px;\n  padding:14px;\n  border:1px solid var(--line);\n  border-radius:17px;\n  background:rgba(255,255,255,.78);\n}\n.share-text-style-head{\n  display:flex;\n  align-items:flex-start;\n  justify-content:space-between;\n  gap:12px;\n  margin-bottom:11px;\n}\n.share-text-style-head strong{font-size:13px}\n.share-text-style-head span{font-size:11px;color:var(--muted)}\n.share-text-style-grid{\n  display:grid;\n  grid-template-columns:1fr 1.25fr;\n  gap:11px;\n}\n.share-text-field{display:grid;gap:6px}\n.share-text-field label{\n  font-size:11px;\n  color:var(--muted);\n  font-weight:850;\n}\n.share-text-field select{\n  width:100%;\n  border:1px solid var(--line);\n  border-radius:12px;\n  background:#fff;\n  color:var(--text);\n  padding:10px 11px;\n  font-size:14px;\n  outline:none;\n}\n.share-font-size-row{\n  display:flex;\n  align-items:center;\n  gap:9px;\n  min-height:42px;\n}\n.share-font-size-row input[type="range"]{\n  flex:1;\n  min-width:0;\n  accent-color:#111722;\n}\n.share-font-size-value{\n  min-width:66px;\n  text-align:right;\n  font-size:12px;\n  font-weight:850;\n  color:var(--text);\n}\n.share-text-style-actions{\n  margin-top:11px;\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  gap:10px;\n}\n.share-text-style-status{\n  min-height:18px;\n  font-size:11px;\n  line-height:1.5;\n  color:var(--muted);\n}\n.share-text-reset{\n  flex:none;\n  padding:8px 10px;\n  font-size:11px;\n}\n@media(max-width:520px){\n  .share-text-style-grid{grid-template-columns:1fr}\n}\n\n'
