req('function currentShareCacheKey(){\n  if(!currentStory)return "";\n  const code=currentStory.tracking_code||currentStory.id||"";\n  return [\n    code,\n    currentShareFormat,\n    currentSharePages.length,\n    settings?.square_post_background_path||"",\n    settings?.square_post_bg_overlay_opacity??"",\n    settings?.square_post_card_opacity??"",\n    settings?.square_post_header_opacity??"",\n    settings?.square_post_footer_opacity??"",\n    settings?.square_post_bg_scale??1,\n    settings?.square_post_bg_x??0,\n    settings?.square_post_bg_y??0\n  ].join("|");\n}\n\n','function currentShareCacheKey(){\n  if(!currentStory)return "";\n  const code=currentStory.tracking_code||currentStory.id||"";\n  return [\n    code,\n    currentShareFormat,\n    currentSharePages.length,\n    settings?.square_post_background_path||"",\n    settings?.square_post_bg_overlay_opacity??"",\n    settings?.square_post_card_opacity??"",\n    settings?.square_post_header_opacity??"",\n    settings?.square_post_footer_opacity??"",\n    settings?.square_post_bg_scale??1,\n    settings?.square_post_bg_x??0,\n    settings?.square_post_bg_y??0,\n    shareFontKey(currentShareFormat),\n    shareFontSize(currentShareFormat)\n  ].join("|");\n}\n\n',1)
req('function shareFontSize(format){\n  // 長文不再一路縮字；維持手機可讀尺寸，放不下就換頁。\n  return format==="square" ? 44 : 52;\n}\n\n','const SHARE_FONT_FAMILIES={\n  original:\'"Noto Serif TC","PingFang TC","Microsoft JhengHei",sans-serif\',\n  ming:\'"Noto Serif TC","PMingLiU","Songti TC",serif\',\n  sans:\'"PingFang TC","Microsoft JhengHei","Noto Sans TC","Arial",sans-serif\',\n  kai:\'"BiauKai","DFKai-SB","KaiTi","STKaiti",serif\'\n};\n\nfunction defaultShareFontSize(format){\n  return format==="square" ? 44 : 52;\n}\n\nfunction shareStyleField(format,type){\n  const prefix=format==="square"?"share_square":"share_story";\n  return `${prefix}_${type}`;\n}\n\nfunction shareFontKey(format){\n  const value=currentStory?.[shareStyleField(format,"font_key")];\n  return Object.prototype.hasOwnProperty.call(SHARE_FONT_FAMILIES,value)\n    ? value\n    : "original";\n}\n\nfunction shareFontFamily(format){\n  return SHARE_FONT_FAMILIES[shareFontKey(format)]||SHARE_FONT_FAMILIES.original;\n}\n\nfunction shareFontSize(format){\n  // 預設完全沿用原版；只有這一篇有自訂值時才覆蓋。\n  const raw=Number(currentStory?.[shareStyleField(format,"font_size")]);\n  if(Number.isFinite(raw) && raw>=28 && raw<=84)return Math.round(raw);\n  return defaultShareFontSize(format);\n}\n\nfunction shareBodyCanvasFont(format,fontSize=shareFontSize(format)){\n  return `700 ${fontSize}px ${shareFontFamily(format)}`;\n}\n\nfunction isOriginalShareTextStyle(format){\n  return shareFontKey(format)==="original"\n    && shareFontSize(format)===defaultShareFontSize(format);\n}\n\nfunction syncShareTextStyleControls(){\n  if(!currentStory)return;\n  const fontKey=shareFontKey(currentShareFormat);\n  const fontSize=shareFontSize(currentShareFormat);\n  $("#shareFontSelect").value=fontKey;\n  $("#shareFontSizeRange").value=String(fontSize);\n  $("#shareFontSizeValue").textContent=`${fontSize} px${fontSize===defaultShareFontSize(currentShareFormat)?" · 原版":""}`;\n  $("#shareTextFormatLabel").textContent=currentShareFormat==="square"?"貼文版":"限動版";\n  $("#shareTextStyleStatus").textContent=isOriginalShareTextStyle(currentShareFormat)\n    ?"目前使用原版設定。"\n    :"已自訂這一篇；切換其他投稿不會跟著改。";\n}\n\nlet shareTextStyleSaveTimer=null;\n\nasync function saveCurrentShareTextStyle(){\n  if(!currentStory)return;\n  const payload={\n    share_story_font_key:currentStory.share_story_font_key??null,\n    share_story_font_size:currentStory.share_story_font_size??null,\n    share_square_font_key:currentStory.share_square_font_key??null,\n    share_square_font_size:currentStory.share_square_font_size??null\n  };\n  const {error}=await supabase.from("messages").update(payload).eq("id",currentStory.id);\n  if(error){\n    console.error("save_share_text_style_failed",error);\n    $("#shareTextStyleStatus").textContent="文字樣式儲存失敗，請稍後再試。";\n    return false;\n  }\n  $("#shareTextStyleStatus").textContent=isOriginalShareTextStyle(currentShareFormat)\n    ?"已恢復原版設定。"\n    :"這一篇的文字樣式已儲存。";\n  return true;\n}\n\nfunction queueShareTextStyleSave(){\n  clearTimeout(shareTextStyleSaveTimer);\n  shareTextStyleSaveTimer=setTimeout(()=>saveCurrentShareTextStyle(),420);\n}\n\nasync function refreshShareTextStylePreview({prepareApple=false}={}){\n  if(!currentStory)return;\n  currentSharePage=0;\n  invalidateAppleShareCache();\n  prepareSharePages(currentStory.content,currentShareFormat);\n  syncShareTextStyleControls();\n  syncShareFormatUI();\n  await drawShareImage(currentStory.content,currentShareFormat,currentSharePage);\n  if(prepareApple)prepareAppleShareFiles();\n}\n\n$("#shareFontSelect").addEventListener("change",async()=>{\n  if(!currentStory)return;\n  currentStory[shareStyleField(currentShareFormat,"font_key")]=$("#shareFontSelect").value;\n  await refreshShareTextStylePreview();\n  await saveCurrentShareTextStyle();\n  prepareAppleShareFiles();\n});\n\n$("#shareFontSizeRange").addEventListener("input",async()=>{\n  if(!currentStory)return;\n  const size=Math.max(28,Math.min(84,Number($("#shareFontSizeRange").value)||defaultShareFontSize(currentShareFormat)));\n  currentStory[shareStyleField(currentShareFormat,"font_size")]=size;\n  await refreshShareTextStylePreview();\n  queueShareTextStyleSave();\n});\n\n$("#shareFontSizeRange").addEventListener("change",async()=>{\n  if(!currentStory)return;\n  clearTimeout(shareTextStyleSaveTimer);\n  await saveCurrentShareTextStyle();\n  invalidateAppleShareCache();\n  prepareAppleShareFiles();\n});\n\n$("#resetShareTextStyleBtn").addEventListener("click",async()=>{\n  if(!currentStory)return;\n  currentStory[shareStyleField(currentShareFormat,"font_key")]=null;\n  currentStory[shareStyleField(currentShareFormat,"font_size")]=null;\n  await refreshShareTextStylePreview();\n  await saveCurrentShareTextStyle();\n  prepareAppleShareFiles();\n});\n\n',1)
req('function syncShareFormatUI(){\n  const cfg=getShareCanvasConfig(currentShareFormat);\n  $$(".share-format-tab").forEach(btn=>{','function syncShareFormatUI(){\n  const cfg=getShareCanvasConfig(currentShareFormat);\n  syncShareTextStyleControls();\n  $$(".share-format-tab").forEach(btn=>{',1)

body_font='ctx.font=`700 ${fontSize}px "Noto Serif TC","PingFang TC","Microsoft JhengHei",sans-serif`;'
if s.count(body_font)<2:
    raise SystemExit("missing share body font markers")
s=s.replace(body_font,'ctx.font=shareBodyCanvasFont(format,fontSize);',2)

p.write_text(s,encoding="utf-8")

# Syntax-check extract
m=re.search(r'<script type="module">(.*?)</script>',s,re.S)
if not m: raise SystemExit("module script missing")
js=m.group(1)
js=re.sub(r'import\s+\{\s*createClient\s*\}\s+from\s+"[^"]+";','const createClient=(...args)=>({});',js,count=1)
Path("/tmp/check.js").write_text(js,encoding="utf-8")

# PWA cache
sw=Path("service-worker.js")
ss=sw.read_text(encoding="utf-8")
if "anonymous-mailbox-v1.18.4" not in ss: raise SystemExit("service worker marker missing")
sw.write_text(ss.replace("anonymous-mailbox-v1.18.4","anonymous-mailbox-v1.18.5",1),encoding="utf-8")
